import numpy as np
def gini(labels):
    _, counts = np.unique(labels, return_counts=True)
    p = counts / counts.sum()
    return 1 - np.sum(p ** 2)
print(gini(np.array([2,2,5,5])))

def diagnose(train, valid):
    if train - valid >= 0.15:
        return 'overfit'
    if train < 0.7 and valid < 0.7:
        return 'underfit'
    return 'review'
print(diagnose(0.99, 0.72))

import numpy as np
def mse(y_true, y_pred):
    residual = np.asarray(y_true) - np.asarray(y_pred)
    return np.mean(residual ** 2)
print(mse([5,9], [7,7]))

import numpy as np
def binary_counts(actual, predicted):
    a = np.asarray(actual)
    p = np.asarray(predicted)
    return {'tp': int(((a==1)&(p==1)).sum()), 'fp': int(((a==0)&(p==1)).sum()), 'fn': int(((a==1)&(p==0)).sum()), 'tn': int(((a==0)&(p==0)).sum())}
print(binary_counts([0,1,1],[1,0,1]))

